ALTER TABLE public.students ADD COLUMN IF NOT EXISTS turma text NOT NULL DEFAULT 'A';
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS estado text NOT NULL DEFAULT 'Activo';
ALTER TABLE public.students ADD CONSTRAINT students_estado_check CHECK (estado IN ('Activo','Desistente'));
DO $$ DECLARE next_id bigint; BEGIN SELECT GREATEST(2600, COALESCE(MAX(id)+1,2600)) INTO next_id FROM public.students; PERFORM setval('public.students_id_seq',GREATEST(next_id,(SELECT last_value FROM public.students_id_seq)),false); END $$;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS genero text;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_genero_check CHECK (genero IS NULL OR genero IN ('M','F'));
CREATE OR REPLACE FUNCTION public.set_own_gender(_genero text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sem sessão'; END IF; IF _genero NOT IN ('M','F') THEN RAISE EXCEPTION 'Género inválido'; END IF; UPDATE public.profiles SET genero=_genero WHERE id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.set_own_gender(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_own_gender(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.staff_teacher_statistics() RETURNS TABLE(user_id uuid, genero text, subject_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.genero,ta.subject_id FROM public.profiles p JOIN public.user_roles r ON r.user_id=p.id AND r.role='professor' LEFT JOIN public.teacher_assignments ta ON ta.user_id=p.id WHERE p.status='APROVADO' AND public.is_staff(auth.uid()) $$;
REVOKE ALL ON FUNCTION public.staff_teacher_statistics() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.staff_teacher_statistics() TO authenticated;